// memory comes in 64-byte lines: touching one float loads 16 of them
NativeArray<float> hp;            // 16 floats = one 64-byte line
float a = hp[0];                  // miss: the whole line comes in
float b = hp[1];                  // hit: already in L1

// sequential walk: the prefetcher loads the next lines ahead of you
for (int i = 0; i < hp.Length; i++) sum += hp[i];
// random walk: every access can be a miss
for (int i = 0; i < idx.Length; i++) sum += hp[idx[i]];

struct Unit                      // 52 bytes
{
    public float3 position;      // 12  hot
    public float3 velocity;      // 12  hot
    public quaternion rotation;  // 16
    public float health;         //  4
    public float cooldown;       //  4
    public int team;             //  4
}

// the loop needs 24 bytes per unit, but all 52 go through the cache
for (int i = 0; i < units.Length; i++)
{
    Unit u = units[i];
    u.position += u.velocity * dt;
    units[i] = u;
}

// SoA: one array per field; the hot loop touches only what it needs
[BurstCompile]
struct MoveJob : IJobParallelFor
{
    public NativeArray<float3> positions;
    [ReadOnly] public NativeArray<float3> velocities;
    public float dt;
    public void Execute(int i) => positions[i] += velocities[i] * dt;
}
// rotation, health, cooldown and team live in arrays of their own

// fully split: 8 x coordinates side by side fill one ymm register
NativeArray<float> px, py, pz, vx, vy, vz;

// hot: read every frame by the movement and collision jobs
NativeList<float3> positions, velocities;
// warm: read by AI a few times a second
NativeList<float> health, cooldown;
// cold: UI and save games
NativeList<FixedString32Bytes> names;

// removing unit i: swap-back in EVERY list, or the indices drift apart
positions.RemoveAtSwapBack(i);
velocities.RemoveAtSwapBack(i);
health.RemoveAtSwapBack(i);
cooldown.RemoveAtSwapBack(i);
names.RemoveAtSwapBack(i);

public struct Velocity : IComponentData { public float3 Value; }

[BurstCompile]
partial struct MoveJob : IJobEntity
{
    public float dt;
    // per chunk: walks only the LocalTransform and Velocity arrays
    void Execute(ref LocalTransform t, in Velocity v) => t.Position += v.Value * dt;
}

