using Unity.Burst;
using Unity.Collections;
using Unity.Jobs;
using Unity.Mathematics;

struct Boid { public float3 position; public float3 velocity; public float4 color; public int flockId; }

[BurstCompile]
struct MoveJob : IJobFor
{
    public NativeArray<float3> positions;              // read and written
    [ReadOnly] public NativeArray<float3> velocities;  // read only
    public float dt;

    public void Execute(int i)
    {
        // 24 useful bytes per boid instead of 44
        positions[i] += velocities[i] * dt;
    }
}
